#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_prepend_resize_fails(void) {
    // Setup: create a buffer with data, and set up so that resize will be needed and will fail
    buffer_t *buf = helper_make_buffer_with_data("world");
    // Assume initial buffer size is exactly the length of "world" (5), so prepending "hello" (5) will require resize
    // We will simulate buffer_resize failure by mocking or stubbing in the real test environment.
    // Here, we just call the function and expect it to return -1 if buffer_resize fails.

    char *to_prepend = "hello";

    // To simulate buffer_resize failure, the test environment should ensure buffer_resize returns -1.
    // Call function under test
    int ret = buffer_prepend(buf, to_prepend);

    // Assert: function returns -1, buffer is unchanged
    TEST_ASSERT_EQUAL_INT(-1, ret);
    helper_assert_buffer_data_equals(buf, "world");
    helper_assert_buffer_length(buf, 5);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_prepend_resize_fails);
    return UNITY_END();
}


